module euler_animal_check(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [4:0] m,\n    input [3:0] src[0:15],\n    input [3:0] dst[0:15],\n    output reg [1:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] PROC_EDGES    = 3'd1;\n    localparam [2:0] CHECK_DEGREES = 3'd2;\n    localparam [2:0] CHECK_CONN    = 3'd3;\n    localparam [2:0] DONE_ST       = 3'd4;\n    \n    reg [2:0] state, next_state;\n    \n    // Internal registers\n    reg [3:0] degree_out[0:7];\n    reg [3:0] degree_in[0:7];\n    reg [7:0] adj_matrix[0:7]; // adj_matrix[i][j] is 1 bit\n    \n    reg [1:0] start_count;\n    reg [1:0] end_count;\n    reg degree_valid;\n    \n    reg [7:0] visited;\n    reg conn_valid;\n    \n    // Counters and indices\n    reg [4:0] edge_counter;\n    reg [2:0] node_counter;\n    reg [2:0] conn_step;\n    reg [7:0] prev_visited;\n    \n    integer i, j;\n\n    // State control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 2'd0;\n            edge_counter <= 5'd0;\n            node_counter <= 3'd0;\n            conn_step <= 3'd0;\n            prev_visited <= 8'd0;\n            conn_valid <= 1'b0;\n            degree_valid <= 1'b0;\n            start_count <= 2'd0;\n            end_count <= 2'd0;\n\n            for (i = 0; i < 8; i = i + 1) begin\n                degree_out[i] <= 4'd0;\n                degree_in[i] <= 4'd0;\n                adj_matrix[i] <= 8'd0;\n            end\n            visited <= 8'd0;\n\n        end else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        edge_counter <= 5'd0;\n                        node_counter <= 3'd0;\n                        start_count <= 2'd0;\n                        end_count <= 2'd0;\n                        degree_valid <= 1'b0;\n                        conn_valid <= 1'b0;\n                        conn_step <= 3'd0;\n                        prev_visited <= 8'd0;\n                        \n                        for (i = 0; i < 8; i = i + 1) begin\n                            degree_out[i] <= 4'd0;\n                            degree_in[i] <= 4'd0;\n                            adj_matrix[i] <= 8'd0;\n                        end\n                        visited <= 8'd0;\n                    end\n                end\n\n                PROC_EDGES: begin\n                    if (edge_counter < m) begin\n                        // Update stats for current edge (non-blocking for synthesis)\n                        if (src[edge_counter] < n) begin\n                            degree_out[src[edge_counter]] <= degree_out[src[edge_counter]] + 4'd1;\n                        end\n                        if (dst[edge_counter] < n) begin\n                            degree_in[dst[edge_counter]] <= degree_in[dst[edge_counter]] + 4'd1;\n                        end\n\n                        // Update adjacency matrix (undirected)\n                        if (src[edge_counter] < n && dst[edge_counter] < n) begin\n                            adj_matrix[src[edge_counter]][dst[edge_counter]] <= 1'b1;\n                            adj_matrix[dst[edge_counter]][src[edge_counter]] <= 1'b1;\n                        end\n\n                        edge_counter <= edge_counter + 5'd1;\n                    end else begin\n                        node_counter <= 3'd0;\n                    end\n                end\n\n                CHECK_DEGREES: begin\n                    if (node_counter < n) begin\n                        if ($signed({1'b0, degree_out[node_counter]}) - $signed({1'b0, degree_in[node_counter]}) == 1) begin\n                            start_count <= start_count + 2'd1;\n                        end else if ($signed({1'b0, degree_in[node_counter]}) - $signed({1'b0, degree_out[node_counter]}) == 1) begin\n                            end_count <= end_count + 2'd1;\n                        end else if (degree_out[node_counter] != degree_in[node_counter]) begin\n                            degree_valid <= 1'b0; // Invalid condition\n                        end\n                        node_counter <= node_counter + 3'd1;\n                    end\n                end\n\n                CHECK_CONN: begin\n                    if (conn_step == 3'd0) begin\n                        // Find first node with non-zero degree\n                        node_counter <= 3'd0;\n                        visited <= 8'd0;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if ((degree_out[i] + degree_in[i]) > 4'd0) begin\n                                visited[i] <= 1'b1;\n                                node_counter <= i[2:0];\n                                i = 8; // Break\n                            end\n                        end\n                        conn_step <= 3'd1;\n                        prev_visited <= visited;\n                    end else if (conn_step <= 3'd7) begin\n                        // Propagate visited using adjacency\n                        prev_visited <= visited;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if (visited[i] && (i < n)) begin\n                                for (j = 0; j < 8; j = j + 1) begin\n                                    if (adj_matrix[i][j] && (j < n)) begin\n                                        visited[j] <= 1'b1;\n                                    end\n                                end\n                            end\n                        end\n                        conn_step <= conn_step + 3'd1;\n                    end else begin\n                        // Check if all non-zero degree nodes are visited\n                        conn_valid <= 1'b1;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if ((degree_out[i] + degree_in[i]) > 4'd0 && !visited[i]) begin\n                                conn_valid <= 1'b0;\n                            end\n                        end\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                next_state = start ? (m == 5'd0 ? DONE_ST : PROC_EDGES) : IDLE;\n            end\n\n            PROC_EDGES: begin\n                if (edge_counter == m) begin\n                    next_state = (m == 5'd0) ? DONE_ST : CHECK_DEGREES;\n                end else begin\n                    next_state = PROC_EDGES;\n                end\n            end\n\n            CHECK_DEGREES: begin\n                if (node_counter >= n) begin\n                    if (start_count > 2'd1 || end_count > 2'd1 || !degree_valid) begin\n                        result = 2'b10; // IMPOSSIBLE\n                        next_state = DONE_ST;\n                    end else begin\n                        result = 2'b00; // Temporary (connectivity check next)\n                        next_state = CHECK_CONN;\n                    end\n                end else begin\n                    next_state = CHECK_DEGREES;\n                end\n            end\n\n            CHECK_CONN: begin\n                if (conn_step > 3'd7) begin\n                    if (conn_valid) begin\n                        result = 2'b01; // POSSIBLE\n                    end else begin\n                        result = 2'b10; // IMPOSSIBLE\n                    end\n                    next_state = DONE_ST;\n                end else begin\n                    next_state = CHECK_CONN;\n                end\n            end\n\n            DONE_ST: begin\n                next_state = IDLE;\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule